def hulltest(g,go):
    H,W=len(g),len(g[0])
    pts=[(i,j) for i in range(H) for j in range(W) if g[i][j]==5]
    def side(a,b,p): return (b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0])
    # andrew monotone chain on (j,i) as x,y
    P=sorted(set((j,i) for i,j in pts))
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lo=[]
    for p in P:
        while len(lo)>=2 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
        lo.append(p)
    up=[]
    for p in reversed(P):
        while len(up)>=2 and cross(up[-2],up[-1],p)<=0: up.pop()
        up.append(p)
    hull=lo[:-1]+up[:-1]
    def inpoly(p):
        x,y=p; inside=False; n=len(hull)
        for k in range(n):
            x1,y1=hull[k]; x2,y2=hull[(k+1)%n]
            if (y1>y)!=(y2>y) and x < (x2-x1)*(y-y1)/(y2-y1)+x1: inside=not inside
        return inside
    res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 and go[i][j]!=0:
                res.append(((i,j),inpoly((j+0.5,i+0.5))))
    return res
