def full(g):
    H,W=len(g),len(g[0])
    zs={(i,j) for i in range(H) for j in range(W) if g[i][j]==0}
    seen=set(); res=[]
    for c in sorted(zs):
        if c in seen: continue
        q=[c]; seen.add(c); reg={c}
        while q:
            y,x=q.pop()
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                n=(y+dy,x+dx)
                if n in zs and n not in seen: seen.add(n); q.append(n); reg.add(n)
        touch={'T':0,'B':0,'L':0,'R':0}
        fives=set()
        for y,x in reg:
            if y==0: touch['T']+=1
            if y==H-1: touch['B']+=1
            if x==0: touch['L']+=1
            if x==W-1: touch['R']+=1
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                n=(y+dy,x+dx)
                if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]==5: fives.add(n)
        sides5=set()
        for y,x in fives:
            if (y+1,x) in reg: sides5.add('T')
            if (y-1,x) in reg: sides5.add('B')
            if (y,x+1) in reg: sides5.add('L')
            if (y,x-1) in reg: sides5.add('R')
        res.append((sorted(reg), len(reg), {k:v for k,v in touch.items() if v}, sorted(sides5), len(fives)))
    return res
